341:         uint256 totalNegativeDeltaB,
342:         uint256 positiveDeltaBCount
343:     ) internal pure returns (WellDeltaB[] memory) {
344:         // most likely case is that all deltaBs are positive
345:         if (positiveDeltaBCount == wellDeltaBs.length) {
346:             // if all deltaBs are positive, need to sop all to zero, so return existing deltaBs
347:             return wellDeltaBs;
348:         }
349: 
350:         if (totalPositiveDeltaB < totalNegativeDeltaB || positiveDeltaBCount == 0) {
351:             // The less than conditional can occur if the twaDeltaB is positive, but the instanteous deltaB is negative or 0
352:             // In that case, no reductions are needed.
353:             // If there are no positive values, no well flooding is needed, return zeros
354:             for (uint256 i = 0; i < positiveDeltaBCount; i++) {
355:                 wellDeltaBs[i].deltaB = 0;
356:             }
357:             return wellDeltaBs;
358:         }
359: 
360:         if (totalPositiveDeltaB < totalNegativeDeltaB) {
361:             for (uint256 i = 0; i < positiveDeltaBCount; i++) {
362:                 wellDeltaBs[i].deltaB = 0;
363:             }
364:             return wellDeltaBs;
365:         }
366: 
367:         uint256 shaveToLevel = totalNegativeDeltaB / positiveDeltaBCount;
368: 
369:         // Loop through positive deltaB wells starting at the highest, re-use the deltaB value slot
370:         // as reduction amount (amount of beans to flood per well).
371:         for (uint256 i = positiveDeltaBCount; i > 0; i--) {
372:             if (shaveToLevel > uint256(wellDeltaBs[i - 1].deltaB)) {
373:                 shaveToLevel += (shaveToLevel - uint256(wellDeltaBs[i - 1].deltaB)) / (i - 1);
374:                 // amount to sop for this well must be zero
375:                 wellDeltaBs[i - 1].deltaB = 0;
376:             } else {
377:                 wellDeltaBs[i - 1].deltaB = wellDeltaBs[i - 1].deltaB - int256(shaveToLevel);
378:             }
379:         }
380:         return wellDeltaBs;
381:     }
